def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_d = sum(1 for a, b in history if b == 'D')
    my_d = sum(1 for a, b in history if a == 'D')

    # Always defect against an always-defecting opponent
    if n >= 2 and opp_d == n:
        return 'D'

    # High defection rate: retaliate
    if n >= 3 and opp_d > n * 0.6:
        return 'D'

    # Early cooperation phase
    if n < 6:
        return 'C'

    # If opponent has never defected, test if they are an unconditional cooperator
    if opp_d == 0:
        if n >= 15:
            if my_d == 0:
                return 'D'
            if my_d > 0 and history[-1][1] == 'C':
                return 'D'
        return 'C'

    # Opponent has defected at least once
    last_my, last_opp = history[-1]

    if last_opp == 'D':
        if last_my == 'D':
            # Both defected last round: try to break the cycle
            recent_opp_d = sum(1 for a, b in history[-5:] if b == 'D')
            if recent_opp_d >= 3:
                return 'D'
            return 'C'
        else:
            # We cooperated, they defected: forgive if they are mostly cooperative
            if opp_d <= 2:
                return 'C'
            if opp_d <= n * 0.3:
                return 'C'
            return 'D'
    else:
        # Opponent cooperated last round
        if last_my == 'D':
            return 'C'
        # Occasionally test a very cooperative opponent
        if opp_d <= n * 0.1 and n > 30:
            if rng.random() < 0.05:
                return 'D'
        return 'C'
